import java.util.*;

class Solution {
    public int cacheMisses(int capacity, int[] pages) {
        // access-ordered LinkedHashMap: iteration starts at the least recently used key
        LinkedHashMap<Integer, Boolean> cache = new LinkedHashMap<>(16, 0.75f, true);
        int misses = 0;
        for (int p : pages) {
            if (cache.get(p) != null) continue;
            misses++;
            if (cache.size() == capacity) cache.remove(cache.keySet().iterator().next());
            cache.put(p, true);
        }
        return misses;
    }
}

