public:
    int cacheMisses(int capacity, vector<int>& pages) {
        list<int> order; // front = most recent
        unordered_map<int, list<int>::iterator> where;
        int misses = 0;
        for (int p : pages) {
            auto it = where.find(p);
            if (it != where.end()) {
                order.splice(order.begin(), order, it->second);
                continue;
            }
            misses++;
            if ((int)order.size() == capacity) {
                where.erase(order.back());
                order.pop_back();
            }
            order.push_front(p);
            where[p] = order.begin();
        }
        return misses;
    }
};

