import "container/list"

func cacheMisses(capacity int, pages []int) int {
    order := list.New() // front = most recent
    where := map[int]*list.Element{}
    misses := 0
    for _, p := range pages {
        if e, ok := where[p]; ok {
            order.MoveToFront(e)
            continue
        }
        misses++
        if order.Len() == capacity {
            back := order.Back()
            delete(where, back.Value.(int))
            order.Remove(back)
        }
        where[p] = order.PushFront(p)
    }
    return misses
}

