import java.util.*;

class Solution {
    public int[] lfuResults(int capacity, String[][] ops) {
        Map<Integer, int[]> store = new HashMap<>(); // key -> {value, count, lastUsed}
        List<Integer> out = new ArrayList<>();
        int tick = 0;
        for (String[] op : ops) {
            tick++;
            int key = Integer.parseInt(op[1]);
            int[] e = store.get(key);
            if (op[0].equals("get")) {
                if (e != null) { e[1]++; e[2] = tick; out.add(e[0]); } else out.add(-1);
                continue;
            }
            int value = Integer.parseInt(op[2]);
            if (e != null) { e[0] = value; e[1]++; e[2] = tick; continue; }
            if (store.size() == capacity) {
                int victim = -1; int[] best = null;
                for (Map.Entry<Integer, int[]> en : store.entrySet()) {
                    int[] v = en.getValue();
                    if (best == null || v[1] < best[1] || (v[1] == best[1] && v[2] < best[2])) { best = v; victim = en.getKey(); }
                }
                store.remove(victim);
            }
            store.put(key, new int[]{value, 1, tick});
        }
        int[] res = new int[out.size()];
        for (int i = 0; i < res.length; i++) res[i] = out.get(i);
        return res;
    }
}

