        key, _ := strconv.Atoi(op[1])
        e, ok := store[key]
        if op[0] == "get" {
            if ok {
                e.count++
                e.last = tick
                out = append(out, e.value)
            } else {
                out = append(out, -1)
            }
            continue
        }
        value, _ := strconv.Atoi(op[2])
        if ok {
            e.value = value
            e.count++
            e.last = tick
            continue
        }
        if len(store) == capacity {
            victim, first := 0, true
            for k, v := range store {
                b := store[victim]
                if first || v.count < b.count || (v.count == b.count && v.last < b.last) {
                    victim, first = k, false
                }
            }
            delete(store, victim)
        }
        store[key] = &entry{value, 1, tick}
    }
    return out
