from collections import defaultdict, OrderedDict

def lfuResults(capacity, ops):
    val, cnt = {}, {}
    buckets = defaultdict(OrderedDict)  # count -> keys in recency order
    min_cnt = 0
    out = []

    def touch(key):
        nonlocal min_cnt
        c = cnt[key]
        del buckets[c][key]
        if not buckets[c]:
            del buckets[c]
            if min_cnt == c:
                min_cnt = c + 1
        cnt[key] = c + 1
        buckets[c + 1][key] = True

    for op in ops:
        key = int(op[1])
        if op[0] == "get":
            if key in val:
                touch(key)
                out.append(val[key])
            else:
                out.append(-1)
            continue
        if key in val:
            val[key] = int(op[2])
            touch(key)
            continue
        if len(val) == capacity:
            victim, _ = buckets[min_cnt].popitem(last=False)
            if not buckets[min_cnt]:
                del buckets[min_cnt]
            del val[victim], cnt[victim]
        val[key], cnt[key] = int(op[2]), 1
        buckets[1][key] = True
        min_cnt = 1
    return out

