import java.util.*;

class Solution {
    private final Map<Integer, Integer> val = new HashMap<>(), cnt = new HashMap<>();
    private final Map<Integer, LinkedHashSet<Integer>> buckets = new HashMap<>();
    private int minCnt = 0;

    private void touch(int key) {
        int c = cnt.get(key);
        LinkedHashSet<Integer> b = buckets.get(c);
        b.remove(key);
        if (b.isEmpty()) { buckets.remove(c); if (minCnt == c) minCnt = c + 1; }
        cnt.put(key, c + 1);
        buckets.computeIfAbsent(c + 1, z -> new LinkedHashSet<>()).add(key);
    }

    public int[] lfuResults(int capacity, String[][] ops) {
        List<Integer> out = new ArrayList<>();
        for (String[] op : ops) {
            int key = Integer.parseInt(op[1]);
            if (op[0].equals("get")) {
                if (val.containsKey(key)) { touch(key); out.add(val.get(key)); } else out.add(-1);
                continue;
            }
            int value = Integer.parseInt(op[2]);
            if (val.containsKey(key)) { val.put(key, value); touch(key); continue; }
            if (val.size() == capacity) {
                LinkedHashSet<Integer> b = buckets.get(minCnt);
                int victim = b.iterator().next();
                b.remove(victim);
                if (b.isEmpty()) buckets.remove(minCnt);
                val.remove(victim); cnt.remove(victim);
            }
            val.put(key, value); cnt.put(key, 1);
            buckets.computeIfAbsent(1, z -> new LinkedHashSet<>()).add(key);
            minCnt = 1;
        }
        int[] res = new int[out.size()];
        for (int i = 0; i < res.length; i++) res[i] = out.get(i);
        return res;
    }
}

