import (
    "container/list"
    "strconv"
)

func lfuResults(capacity int, ops [][]string) []int {
    type info struct {
        value, count int
        elem         *list.Element
    }
    infos := map[int]*info{}
    buckets := map[int]*list.List{} // count -> keys, front = least recent
    minCnt := 0
    bucket := func(c int) *list.List {
        if buckets[c] == nil {
            buckets[c] = list.New()
        }
        return buckets[c]
    }
    touch := func(key int) {
        e := infos[key]
        b := buckets[e.count]
        b.Remove(e.elem)
        if b.Len() == 0 {
            delete(buckets, e.count)
            if minCnt == e.count {
                minCnt++
            }
        }
        e.count++
        e.elem = bucket(e.count).PushBack(key)
    }
    out := []int{}
    for _, op := range ops {
        key, _ := strconv.Atoi(op[1])
        e, ok := infos[key]
        if op[0] == "get" {
            if ok {
                touch(key)
                out = append(out, e.value)
            } else {
                out = append(out, -1)
            }
            continue
        }
        value, _ := strconv.Atoi(op[2])
        if ok {
            e.value = value
            touch(key)
            continue
        }
        if len(infos) == capacity {
            b := buckets[minCnt]
            front := b.Front()
            b.Remove(front)
            if b.Len() == 0 {
                delete(buckets, minCnt)
            }
            delete(infos, front.Value.(int))
        }
        infos[key] = &info{value, 1, bucket(1).PushBack(key)}
        minCnt = 1
    }
    return out
}

