type LRUCache struct {
    capacity int
    values   map[int]int
    order    []int // least recent first
}

func Constructor(capacity int) LRUCache {
    return LRUCache{capacity: capacity, values: map[int]int{}}
}

func (this *LRUCache) touch(key int) {
    if _, ok := this.values[key]; ok {
        for i, k := range this.order {
            if k == key {
                this.order = append(this.order[:i], this.order[i+1:]...)
                break
            }
        }
    }
    this.order = append(this.order, key)
}

func (this *LRUCache) Get(key int) int {
    v, ok := this.values[key]
    if !ok {
        return -1
    }
    this.touch(key)
    return v
}

func (this *LRUCache) Put(key, value int) {
    this.touch(key)
    this.values[key] = value
    if len(this.values) > this.capacity {
        oldest := this.order[0]
        this.order = this.order[1:]
        delete(this.values, oldest)
    }
}

