import java.util.*;

class LRUCache {
    private static class DNode {
        int key, val;
        DNode prev, next;
        DNode(int key, int val) { this.key = key; this.val = val; }
    }

    private final int capacity;
    private final Map<Integer, DNode> map = new HashMap<>();
    private final DNode head = new DNode(0, 0), tail = new DNode(0, 0); // sentinels; most recent after head

    public LRUCache(int capacity) {
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    private void remove(DNode node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    private void addFront(DNode node) {
        node.prev = head;
        node.next = head.next;
        head.next.prev = node;
        head.next = node;
    }

    public int get(int key) {
        DNode node = map.get(key);
        if (node == null) return -1;
        remove(node);
        addFront(node);
        return node.val;
    }

    public void put(int key, int value) {
        if (map.containsKey(key)) remove(map.get(key));
        DNode node = new DNode(key, value);
        map.put(key, node);
        addFront(node);
        if (map.size() > capacity) {
            DNode lru = tail.prev;
            remove(lru);
            map.remove(lru.key);
        }
    }
}

