class LRUCache {
    struct DNode {
        int key, val;
        DNode *prev = nullptr, *next = nullptr;
        DNode(int k, int v) : key(k), val(v) {}
    };

    int capacity;
    unordered_map<int, DNode*> map;
    DNode *head, *tail; // sentinels; most recent after head

    void remove(DNode* node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    void addFront(DNode* node) {
        node->prev = head;
        node->next = head->next;
        head->next->prev = node;
        head->next = node;
    }

public:
    LRUCache(int capacity) : capacity(capacity) {
        head = new DNode(0, 0);
        tail = new DNode(0, 0);
        head->next = tail;
        tail->prev = head;
    }

    int get(int key) {
        auto it = map.find(key);
        if (it == map.end()) return -1;
        DNode* node = it->second;
        remove(node);
        addFront(node);
        return node->val;
    }

    void put(int key, int value) {
        auto it = map.find(key);
        if (it != map.end()) {
            remove(it->second);
            delete it->second;
        }
        DNode* node = new DNode(key, value);
        map[key] = node;
        addFront(node);
        if ((int) map.size() > capacity) {
            DNode* lru = tail->prev;
            remove(lru);
            map.erase(lru->key);
            delete lru;
        }
    }
};

