type dNode struct {
    key, val   int
    prev, next *dNode
}

type LRUCache struct {
    capacity   int
    nodes      map[int]*dNode
    head, tail *dNode // sentinels; most recent after head
}

func Constructor(capacity int) LRUCache {
    head, tail := &dNode{}, &dNode{}
    head.next, tail.prev = tail, head
    return LRUCache{capacity: capacity, nodes: map[int]*dNode{}, head: head, tail: tail}
}

func (this *LRUCache) remove(node *dNode) {
    node.prev.next, node.next.prev = node.next, node.prev
}

func (this *LRUCache) addFront(node *dNode) {
    node.prev, node.next = this.head, this.head.next
    this.head.next.prev = node
    this.head.next = node
}

func (this *LRUCache) Get(key int) int {
    node, ok := this.nodes[key]
    if !ok {
        return -1
    }
    this.remove(node)
    this.addFront(node)
    return node.val
}

func (this *LRUCache) Put(key, value int) {
    if old, ok := this.nodes[key]; ok {
        this.remove(old)
    }
    node := &dNode{key: key, val: value}
    this.nodes[key] = node
    this.addFront(node)
    if len(this.nodes) > this.capacity {
        lru := this.tail.prev
        this.remove(lru)
        delete(this.nodes, lru.key)
    }
}
